/* Work queues share the same pending items as Meu dia. All sources are fictional. */
function stamp(value){return value?new Date(value).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}):'Não informado';}
function moduleOf(p){return p.audit||p.waiting?.module==='Auditoria'?'Auditoria':p.stage===0?'Cotações':'Embarques';}
function changeKey(p){return p.id+':'+p.date;}
function workItems(){
  return processes.flatMap(p=>{
    const items=[];
    if(p.action)items.push({p,kind:'decision',title:p.action.title,owner:p.action.owner,executor:p.action.owner,deadline:p.action.deadline,module:moduleOf(p),cmd:'detail',cta:p.action.cta});
    if(p.waiting)items.push({p,kind:'waiting',title:p.waiting.title,owner:p.owner,executor:p.waiting.executor,deadline:p.waiting.expected,module:moduleOf(p),cmd:'request',cta:'Solicitar atualização'});
    if(p.risk&&!state.eventReviews.includes(changeKey(p)))items.push({p,kind:'review',title:'Revisar impacto da nova chegada',owner:p.owner,executor:p.owner,deadline:null,module:'Embarques',cmd:'reviewchange',cta:'Revisar mudança'});
    return items;
  });
}
function urgency(w){return !w.deadline?'undated':new Date(w.deadline)<NOW?'overdue':w.deadline.startsWith('2026-09-10')?'today':'later';}
function workDeadline(w){return !w.deadline?'Sem prazo informado':`${urgency(w)==='overdue'?'Vencido · ':''}${stamp(w.deadline)}`;}
function workSort(a,b){const rank={overdue:0,today:1,undated:2,later:3};return rank[urgency(a)]-rank[urgency(b)]||new Date(a.deadline||'2099-01-01')-new Date(b.deadline||'2099-01-01');}
function filteredWork(ignoreFlag=false){
  const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  return workItems().filter(w=>(state.opScope!=='mine'||w.p.owner===state.profile)&&(!state.opExecutor||state.opExecutor==='all'||w.executor===state.opExecutor)&&(state.owner==='all'||w.owner===state.owner)&&(state.workModule==='all'||w.module===state.workModule)&&(state.workKind==='all'||w.kind===state.workKind)&&(ignoreFlag||state.flag==='all'||urgency(w)===state.flag||state.flag==='waiting'&&w.kind==='waiting')&&norm([w.title,w.p.name,w.p.po,w.p.id,w.p.supplier,w.executor].join(' ')).includes(norm(state.search))).sort(workSort);
}
function filteredProcesses(){return [...new Map(filteredWork().map(w=>[w.p.id,w.p])).values()];}
function returnCard(p){
  const w=p.waiting,late=w.expected&&new Date(w.expected)<NOW;
  return `<article class="return-card"><div class="return-heading"><div><span class="eyebrow">${moduleOf(p)} · ${p.po}</span><h3>${w.title}</h3><p class="small muted">${p.name} · ${p.supplier}</p></div><span class="pill ${late?'danger':''}">${late?'Retorno vencido':w.expected?'Retorno combinado':'Sem prazo combinado'}</span></div><p class="return-effect">${w.effect}</p><dl class="return-facts"><div><dt>Depende de</dt><dd>${w.executor}</dd></div><div><dt>Retorno combinado</dt><dd>${stamp(w.expected)}</dd></div><div><dt>Último contato</dt><dd>${stamp(w.lastContact)}</dd></div><div><dt>Pendente desde</dt><dd>${w.since?dateLabel(w.since):'Não informado'} · ${person(p.owner)} acompanha</dd></div></dl>${state.drafts[p.id]?'<p class="draft-note">Rascunho salvo · ainda não enviado</p>':''}<div class="return-actions"><button class="button primary" data-cmd="request" data-id="${p.id}">${state.drafts[p.id]?'Revisar solicitação':'Solicitar atualização'}</button><button class="link-button" data-cmd="detail" data-id="${p.id}">Ver contexto</button><button class="link-button" data-cmd="followup" data-id="${p.id}">Acompanhar ${stamp(w.followup+'-03:00')}</button></div></article>`;
}
/* "Atualizações" (02/10/2026): o feed de LEITURA que substituiu "Mudanças
   relevantes". Espelha o UpdatesFeed do portal (app/portal/_shared/updates-feed.tsx):
   sem "Já vi", sem contador, sem CTA de tarefa; cada linha leva ao contexto.
   O que pede ação continua em "Fazer agora" e em "Onde intervir". */
function updatesFeed(list,{max=5,description=''}={}){
  const sorted=[...list].sort((a,b)=>b.e.time.localeCompare(a.e.time)),shown=sorted.slice(0,max);
  const item=({p,e})=>`<li><button class="update-row" data-cmd="detail" data-id="${p.id}"><i class="update-dot" aria-hidden="true"></i><span><strong>${esc(e.title)}</strong><small>${[e.time,p.po,esc(p.supplier)].join(' · ')}${e.before?` · ${e.before} → ${e.after}`:''}</small></span>${icon('chevron')}</button></li>`;
  return `<section class="op-panel updates-feed" aria-labelledby="updates-title"><div class="op-panel-heading"><div><h3 id="updates-title">Atualizações</h3>${description?`<p class="small muted">${description}</p>`:''}</div></div>${shown.length?`<ul class="update-list">${shown.map(item).join('')}</ul>`:'<p class="op-caption">Nenhuma atualização recente neste escopo.</p>'}${sorted.length>shown.length?`<p class="op-panel-note">Mostrando as ${shown.length} mais recentes de ${sorted.length}.</p>`:''}</section>`;
}
function renderDay(){
  const ts=tasks(),ws=waits(),late=ts.filter(p=>due(p)==='overdue'),today=ts.filter(p=>due(p)==='today');
  const shown=[...ts].sort((a,b)=>new Date(a.action.deadline||'2099-01-01')-new Date(b.action.deadline||'2099-01-01'));
  // Escala de urgencia do portal (app/portal/_shared/urgency.ts, 30/09/2026):
  // vencida = critico, vence hoje = atencao, o resto sem cor. A frase de cima e
  // a mesma pergunta que a Home responde: "o que exige sua atencao hoje".
  // FOCO (Orsi, 02/10/2026): a frase + "Fazer agora" e tudo. Os tres cards de
  // resumo sairam (repetiam as secoes), "Aguardando retorno" fica recolhido e
  // "Mudancas relevantes" virou o feed Atualizacoes, na Operacao e em Embarques.
  const need=late.length+today.length;
  const summary=need?`<p class="attention-summary"><strong>${need}</strong> ${need===1?'item exige':'itens exigem'} sua atenção hoje${late.length?` · <span class="red">${late.length} com prazo vencido</span>`:''}${today.length?` · <span class="amber">${today.length} ${today.length===1?'vence':'vencem'} hoje</span>`:''}</p>`:`<p class="attention-summary">Nada exige sua atenção hoje.</p>`;
  return `${summary}<div class="day-focus"><section class="surface"><div class="section-head"><div class="section-title"><h2>Fazer agora</h2><span class="count">${shown.length}</span></div><span class="small muted">Decisões e pendências</span></div><div class="scope-tabs"><button data-cmd="scope" data-value="mine" class="${state.scope==='mine'?'active':''}" aria-pressed="${state.scope==='mine'}">Minhas ações</button><button data-cmd="scope" data-value="shared" class="${state.scope==='shared'?'active':''}" aria-pressed="${state.scope==='shared'}">Fila compartilhada</button></div>${shown.length?shown.map(p=>`<div class="task-row ${due(p)==='overdue'?'urgent':due(p)==='today'?'today':''}"><span class="task-marker"></span><div><div class="task-title">${p.action.title}</div><p class="task-meta">${p.po} · ${p.supplier} · ${p.name}</p><div class="task-bottom">${due(p)==='later'?`<span class="pill">${dueLabel(p)}</span>`:`<span class="pill ${due(p)==='overdue'?'danger':'warning'}">${dueLabel(p)}</span>`}<span>${moduleOf(p)} · ${person(p.action.owner)}</span></div></div><button class="button" data-cmd="detail" data-id="${p.id}">${p.action.cta}</button></div>`).join(''):empty('Nenhuma ação para você agora','O trabalho da equipe está na Operação.')}</section><details class="surface waiting" id="waiting-list" ${state.waitingOpen?'open':''}><summary class="section-head"><div class="section-title"><h2>Aguardando retorno</h2><span class="count">${ws.length}</span></div><span class="small muted">Com terceiros · abra para acompanhar</span></summary>${ws.length?ws.sort((a,b)=>new Date(a.waiting.expected||'2099-01-01')-new Date(b.waiting.expected||'2099-01-01')).map(returnCard).join(''):empty('Nenhum retorno pendente','Novos acompanhamentos aparecerão aqui.')}</details></div>`;
}
function renderWorkQueue(){
  const rows=filteredWork(),base=filteredWork(true),hasFilter=state.owner!=='all'||state.workModule!=='all'||state.workKind!=='all'||(state.opExecutor&&state.opExecutor!=='all')||state.flag!=='all'||state.search;
  const chip=(key,label,n)=>`<button class="filter-chip ${state.flag===key?'active':''}" data-cmd="flag" data-value="${key}" aria-pressed="${state.flag===key}">${label}<strong>${n}</strong></button>`;
  return `<div class="queue-heading"><div><h2>Fila de trabalho</h2><p>Pendências de todos os módulos, organizadas pelo que precisa avançar.</p></div><span class="queue-total"><strong>${rows.length}</strong> pendências</span></div><div class="toolbar"><label class="searchbox">${icon('search')}<input id="search" type="search" aria-label="Buscar pendência, PO, fornecedor ou responsável" placeholder="Buscar pendência, PO ou fornecedor" value="${esc(state.search)}"></label><select class="select-filter" id="owner" aria-label="Responsável pelo acompanhamento" ${state.opScope==='mine'?'hidden':''}><option value="all">Todos os responsáveis</option>${['Mariana','Beatriz','Rafael'].map(n=>`<option ${state.owner===n?'selected':''}>${n}</option>`).join('')}</select><select class="select-filter" id="work-module" aria-label="Módulo"><option value="all">Todos os módulos</option>${['Cotações','Embarques','Auditoria'].map(n=>`<option ${state.workModule===n?'selected':''}>${n}</option>`).join('')}</select><select class="select-filter" id="work-kind" aria-label="Tipo de trabalho"><option value="all">Todos os tipos</option>${[['decision','Decisões'],['waiting','Retornos'],['review','Revisões de chegada']].map(([v,n])=>`<option value="${v}" ${state.workKind===v?'selected':''}>${n}</option>`).join('')}</select>${hasFilter?'<button class="link-button" data-cmd="clearop">Limpar filtros</button>':''}</div>${state.opExecutor&&state.opExecutor!=='all'?`<p class="small muted">Depende de: ${esc(state.opExecutor)}</p>`:''}<div class="op-summary">${chip('all','Tudo',base.length)}${chip('overdue','Vencidas',base.filter(w=>urgency(w)==='overdue').length)}${chip('today','Para hoje',base.filter(w=>urgency(w)==='today').length)}${chip('waiting','Aguardando retorno',base.filter(w=>w.kind==='waiting').length)}</div><section class="surface">${rows.length?`<div class="table-wrap"><table class="work-table"><thead><tr><th>O que precisa avançar</th><th>Responsabilidade</th><th>Prazo</th><th>Próximo passo</th></tr></thead><tbody>${rows.map(w=>`<tr><td><span class="eyebrow">${w.module} · ${w.p.po}</span><strong>${w.title}</strong><small>${w.p.supplier} · ${w.p.name}</small></td><td><strong>${w.executor}</strong><small>${w.kind==='waiting'?`${w.owner} acompanha`:'Responsável pela ação'}</small></td><td><span class="pill ${urgency(w)==='overdue'?'danger':urgency(w)==='today'?'warning':''}">${workDeadline(w)}</span><small>${w.kind==='waiting'?'Prazo de resposta':w.kind==='review'?'Revisão sem prazo atribuído':'Prazo da decisão'}</small></td><td><button class="button" data-cmd="${w.cmd}" data-id="${w.p.id}">${w.cta}</button>${state.drafts[w.p.id]&&w.kind==='waiting'?'<small>Rascunho não enviado</small>':''}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma pendência neste recorte','Altere os filtros para consultar o restante da equipe.')}<div class="table-footer"><span>${new Set(rows.map(w=>w.p.id)).size} processos com trabalho neste recorte</span><span>Uma solicitação preparada não encerra a pendência.</span></div></section><p class="board-foot">Prazos de resposta e responsáveis vêm de registros explícitos do cenário. Sem prazo informado não significa atraso. A chegada ao porto não representa entrega na fábrica.</p>`;
}
function requestUpdate(id){
  const p=processes.find(p=>p.id===id);if(!p?.waiting)return;const w=p.waiting,draft=state.drafts[id]||{};drawerProcess=id;
  const message=`Olá, ${w.executor}.\n\nPode atualizar o andamento de “${w.title}”, referente ao ${p.po} — ${p.name}, fornecedor ${p.supplier}?${w.expected?' O retorno combinado era '+stamp(w.expected)+'.':''}\n\n${w.effect}\n\nPor favor, informe o status e a previsão de retorno. Obrigado.`;
  showDrawer('Solicitar atualização',`${p.po} · ${p.supplier}`,`<div class="notice">Rascunho de demonstração. Nenhum e-mail será enviado e o último contato não será alterado.</div><p class="return-effect">${w.title} · depende de ${w.executor}</p><form id="request-form"><label class="form-field">Destinatário<input type="email" id="request-recipient" value="${esc(draft.recipient||w.contact||'')}" placeholder="Informe o e-mail do responsável" required></label>${!w.contact?'<p class="small muted">Este cenário não tem contato cadastrado. Revise o destinatário antes de preparar a solicitação.</p>':''}<label class="form-field">Mensagem<textarea id="request-message" rows="9" required>${esc(draft.message||message)}</textarea></label><p id="request-error" role="alert" class="red small"></p><div class="form-actions"><button type="button" class="button primary" data-cmd="savedraft" data-id="${id}">Salvar rascunho</button><button type="button" class="button" data-cmd="detail" data-id="${id}">Voltar ao contexto</button></div></form>`);
}
function saveRequest(id){
  const form=$('#request-form'),message=$('#request-message').value.trim();if(!form.reportValidity())return;
  if(!message){$('#request-error').textContent='Escreva uma mensagem para salvar o rascunho.';return;}
  state.drafts[id]={recipient:$('#request-recipient').value.trim(),message};
  try{localStorage.setItem(KEY,JSON.stringify(state));}catch{$('#request-error').textContent='O navegador não permitiu salvar. Mantenha o texto aberto para copiá-lo.';return;}
  render();requestUpdate(id);notify('Rascunho salvo neste navegador. Nenhuma mensagem enviada.');
}
function reviewChange(id){
  const p=processes.find(p=>p.id===id);if(!p)return;drawerProcess=id;
  const reviewed=state.eventReviews.includes(changeKey(p));
  showDrawer('Revisar impacto da chegada',`${p.po} · ${p.supplier}`,`<h3>${p.name}</h3><div class="delta"><span>Primeira previsão<br>${dateLabel(p.baseline)}</span>${icon('arrow')}<strong>Previsão atual<br>${dateLabel(p.date)}</strong></div><p class="return-effect">Confira o impacto no planejamento interno. Estas datas se referem à chegada ao porto; não há previsão de disponibilidade na fábrica neste cenário.</p><p class="source-note">${p.events[0]?.source||p.source} · ${p.updated}<br>Marcar como revisado registra sua avaliação. Não altera a previsão nem resolve o atraso.</p>${p.owner!==state.profile?`<p class="small muted">Revisão atribuída a ${p.owner}. Troque o perfil de exemplo para registrar a avaliação.</p>`:''}<div class="form-actions"><button class="button primary" data-cmd="confirmreview" data-id="${id}" ${reviewed||p.owner!==state.profile?'disabled':''}>${reviewed?'Mudança revisada':'Marcar como revisado'}</button><button class="button" data-cmd="detail" data-id="${id}">Ver contexto</button></div>`);
}

